#!/usr/bin/env python3
"""
Round 196o (culprits), 14 October 2026. Needs round 195o.

Settings box in two columns; Faster map beside Stuck?; Layer colours in the Layers box; Woodlands note out.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 196o (14 October)\n\nNeeds round 195o (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- The Woodlands note ("In the spirit of Robert Griffing...") is taken out,\n  and with nothing left in it, Woodlands\' i button too (themedNotes deletes\n  BM_NOTES.wood).\n- Faster map sits on the Stuck? line, to the right of it, white like the\n  reload button. Its sentence is behind a small i (#lite-info): on hover,\n  or opened on a click, closed by a click elsewhere.\n- Hologram: Basemap underneath is now the first of the hologram\'s options,\n  shown with them when the hologram is picked (index.html addSwitch).\n- The settings box in two columns (settingsLayout, run after the box is\n  written, so the code writing and wrapping each part is left as it was):\n  Basemap left; View right in one column (Globe, Flat map, Place names,\n  Streets, then North up beside the zoom buttons, then Snap back and Leave\n  Earth at the foot). The columns stretch to the same height; the basemap\n  list spreads to fill. 3D terrain runs the whole width under them.\n  "Streets and places" is now "Streets". The North up caption is hidden\n  (its title says it).\n- Layer colours (the wheel) move to the foot of the Layers box\n  (#layer-colours), wired there.\n- Checked in a headless browser in the sandbox (stand-in libraries, no\n  map tiles), not yet in a live browser.\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round196o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 195o" not in h.read_text(encoding="utf-8"):
        sys.exit("round196o: round 195o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round196o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/index.html", "map/test.mjs", check=False)
            sys.exit("round196o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round196o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
